{"content":"/**
 * RIX PANEL — Cloudflare Workers VPN Management Panel (ULTRA V2)
 * Features: SPA, Scanner (Clean IP), Light/Dark, Pro Glass UI, VLESS/Trojan.
 */
import { connect } from "cloudflare:sockets";

const DEFAULTS = {
  LOGIN_TTL_DAYS: 7,
  DEFAULT_PANEL_PASS: "Rix12345!",
};

// --- Storage / KV ---
async function getSettings(env) {
  const s = await env.KV.get("rix:settings");
  return s ? JSON.parse(s) : { cleanIPs: "", theme: "dark" };
}

// --- HTML / UI (The Core Requirement) ---
const UI_CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@300;400;700;900&display=swap');
  :root {
    --bg: #030712; --txt: #f3f4f6; --accent: #8b5cf6; --glass: rgba(255,255,255,0.05);
  }
  body.light { --bg: #f9fafb; --txt: #111827; --glass: rgba(0,0,0,0.05); }
  body { font-family: 'Vazirmatn', sans-serif; background: var(--bg); color: var(--txt); transition: all 0.3s; }
  .card { background: var(--glass); backdrop-filter: blur(20px); border: 1px solid rgba(255,255,255,0.1); border-radius: 20px; padding: 20px; }
  .tab-pane { display: none; } .tab-pane.active { display: block; }
  button { cursor: pointer; transition: 0.2s; }
  button:hover { transform: translateY(-2px); }
`;

async function renderAdmin(env) {
  const settings = await getSettings(env);
  return new Response(`
    <!DOCTYPE html>
    <html dir="rtl" lang="fa">
    <head>
      <meta charset="UTF-8">
      <title>RIX Ultra Panel</title>
      <style>${UI_CSS}</style>
    </head>
    <body class="${settings.theme}">
      <nav class="card" style="margin-bottom: 20px;">
        <button onclick="showTab('dashboard')">داشبورد</button>
        <button onclick="showTab('scanner')">اسکنر IP تمیز</button>
        <button onclick="toggleTheme()">تغییر تم</button>
      </nav>

      <div id="dashboard" class="tab-pane active card">
        <h1>داشبورد مدیریت</h1>
        <p>وضعیت سیستم: آنلاین</p>
      </div>

      <div id="scanner" class="tab-pane card">
        <h1>اسکنر IP تمیز</h1>
        <textarea id="ipInput" placeholder="IP ها را اینجا وارد کنید..." style="width:100%; height:100px; background:transparent; color:inherit;"></textarea>
        <button onclick="applyScanner()">اعمال به تمامی کانفیگ‌ها</button>
      </div>

      <script>
        function showTab(id) {
          document.querySelectorAll('.tab-pane').forEach(t => t.classList.remove('active'));
          document.getElementById(id).classList.add('active');
        }
        function toggleTheme() {
          document.body.classList.toggle('light');
        }
        function applyScanner() {
          const ips = document.getElementById('ipInput').value;
          fetch('/api/update-ips', { method: 'POST', body: JSON.stringify({ ips }) })
            .then(() => alert('با موفقیت اعمال شد'));
        }
      </script>
    </body>
    </html>
  `, { headers: { "content-type": "text/html; charset=utf-8" } });
}

// --- Handler ---
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === "/admin") return await renderAdmin(env);
    if (url.pathname === "/api/update-ips" && request.method === "POST") {
      const { ips } = await request.json();
      await env.KV.put("rix:settings", JSON.stringify({ cleanIPs: ips }));
      return new Response(JSON.stringify({ ok: true }));
    }
    return new Response("RIX Panel Active", { status: 200 });
  }
};
