  index: "rix:users:index",          // JSON array of user ids
  user: (id) => `rix:user:${id}`,    // JSON user object
  uuid: (uuid) => `rix:uuid:${uuid}`,// user.id (secondary index for fast lookup)
  sub: (sub) => `rix:sub:${sub}`,    // user.id
  settings: "rix:settings",          // JSON settings (non-secret only + pass override)
  auth: (tok) => `rix:auth:${tok}`,  // JSON {exp,v}
