  const now = Date.now();
  const admin = blankUser({
    id: newId(), uuid, name: "admin", note: "default admin",
    sub: newSub(), enable: true, protocols: settings.defaultProtocols?.length ? settings.defaultProtocols : ["vless", "trojan"],
    quota: 0, expiry: 0, used: { u: 0, d: 0 }, lastSeen: 0, created: now,
