      host = `${buf[o]}.${buf[o+1]}.${buf[o+2]}.${buf[o+3]}`; o += 4;
    } else if (atyp === 3) {
      if (buf.length < o + 1) return { ok: false, reason: "short" };
      const L = buf[o]; o += 1;
      if (!L || buf.length < o + L + 2) return { ok: false, reason: "short" };
      host = td(buf.slice(o, o + L)); o += L;
      if (!host || host.length > 253) return { ok: false, reason: "addr" };
    } else if (atyp === 4) {
      if (buf.length < o + 16 + 2) return { ok: false, reason: "short" };
      const parts = [];
      for (let i = 0; i < 8; i++) parts.push(((buf[o+i*2]<<8)|buf[o+i*2+1]).toString(16));
      host = `[${parts.join(":")}]`; o += 16;
    } else return { ok: false, reason: "atyp" };
    if (buf.length < o + 2 || buf[o] !== 0x0d || buf[o+1] !== 0x0a) return { ok: false, reason: "crlf" };
    o += 2;
    if (!port || port > 65535) return { ok: false, reason: "port" };
    return { ok: true, host, port, headerLen: o };
  } catch { return { ok: false, reason: "ex" }; }
}

/* ============================================================
 * 9. TCP relay helpers
 * ========================================================== */
function safeClose(...xs) {
  for (const x of xs) {
    try {
      if (!x) continue;
      if (typeof x.close === "function") { try { x.close(); } catch { /* ignore */ } continue; }
      if (typeof x.cancel === "function") { try { x.cancel(); } catch { /* ignore */ } continue; }
    } catch { /* ignore */ }
  }
}
async function addTraffic(env, userId, up, down) {
  try {
    const u = await getUser(env, userId);
    if (!u) return;
    u.used = u.used || { u: 0, d: 0 };
    u.used.u = (Number(u.used.u) || 0) + (Number(up) || 0);
    u.used.d = (Number(u.used.d) || 0) + (Number(down) || 0);
    u.lastSeen = Date.now();
    if (isQuotaHit(u)) u.quotaHit = true;
    await saveUser(env, u);
  } catch { /* accounting must never crash relay */ }
}
async function relayTcp(env, ws, tcp, userId, firstPayload) {
  // WS -> TCP and TCP -> WS, fully guarded. No stream/WS left un-cleaned.
  let up = 0, down = 0, closed = false;
  const reader = tcp.readable.getReader();
  const writer = tcp.writable.getWriter();
  const closeAll = () => {
    if (closed) return; closed = true;
    try { reader.releaseLock(); } catch { /* ignore */ }
    try { writer.releaseLock(); } catch { /* ignore */ }
    safeClose(tcp, ws);
  };
  // TCP -> WS pump
  const tcpToWs = (async () => {
    try {
      while (true) {
        let r;
        try { r = await reader.read(); } catch { break; }
        if (!r || r.done) break;
        const chunk = r.value;
        down += chunk.byteLength;
        try { ws.send(chunk); } catch { break; }
      }
    } catch { /* pump ends */ }
    try { ws.close(); } catch { /* ignore */ }
  })();
  try {
    if (firstPayload && firstPayload.length) {
      up += firstPayload.length;
      try { await writer.write(firstPayload); } catch { closeAll(); await addTraffic(env, userId, up, down); return; }
    }
    ws.addEventListener("message", async (ev) => {
      try {
        const d = await wsToBytes(ev.data);
        up += d.length;
        await writer.write(d);
      } catch { try { ws.close(); } catch { /* ignore */ } }
    });
    ws.addEventListener("close", () => closeAll());
    ws.addEventListener("error", () => closeAll());
    await tcpToWs;
  } catch { /* ignore */ }
  closeAll();
  await addTraffic(env, userId, up, down);
}

async function handleVlessSession(env, ws, user, early) {
  const userBytes = uuidToBytes(user.uuid);
  let buf = early && early.length ? early : null;
  const userId = user.id;
  const failClose = async (reason) => {
    // internal log only (no secrets)
    try { console.log(`[rix] vless reject: ${reason}`); } catch { /* ignore */ }
    safeClose(ws);
  };
  try {
    if (!buf) {
      // wait for first packet (bounded, never hangs worker: 10s cap)
      buf = await new Promise((resolve) => {
        const t = setTimeout(() => resolve(null), 10000);
        const onMsg = async (ev) => {
          try {
            const d = await wsToBytes(ev.data);
            clearTimeout(t); resolve(d);
          } catch { clearTimeout(t); resolve(null); }
        };
        ws.addEventListener("message", onMsg, { once: true });
        ws.addEventListener("close", () => { clearTimeout(t); resolve(null); }, { once: true });
        ws.addEventListener("error", () => { clearTimeout(t); resolve(null); }, { once: true });
      });
    }
    if (!buf || !buf.length) { await failClose("empty"); return; }
    const p = parseVless(buf, userBytes);
    if (!p.ok) { await failClose(p.reason); return; }
    let tcp;
    try { tcp = await connect({ hostname: p.host.replace(/^\[|\]$/g, ""), port: p.port }); }
    catch { safeClose(ws); return; }
    try { ws.send(new Uint8Array([0, 0])); } catch { safeClose(tcp, ws); return; }
    const rest = buf.slice(p.headerLen);
    await relayTcp(env, ws, tcp, userId, rest);
  } catch { safeClose(ws); }
}
async function handleTrojanSession(env, ws, user, early) {
  let buf = early && early.length ? early : null;
  const failClose = async (reason) => {
    try { console.log(`[rix] trojan reject: ${reason}`); } catch { /* ignore */ }
    safeClose(ws);
  };
  try {
    if (!buf) {
      buf = await new Promise((resolve) => {
        const t = setTimeout(() => resolve(null), 10000);
        const onMsg = async (ev) => {
          try {
            const d = await wsToBytes(ev.data);
            clearTimeout(t); resolve(d);
          } catch { clearTimeout(t); resolve(null); }
        };
        ws.addEventListener("message", onMsg, { once: true });
        ws.addEventListener("close", () => { clearTimeout(t); resolve(null); }, { once: true });
        ws.addEventListener("error", () => { clearTimeout(t); resolve(null); }, { once: true });
      });
    }
    if (!buf || !buf.length) { await failClose("empty"); return; }
    const p = parseTrojan(buf, user.uuid);
    if (!p.ok) { await failClose(p.reason); return; }
    let tcp;
    try { tcp = await connect({ hostname: p.host.replace(/^\[|\]$/g, ""), port: p.port }); }
    catch { safeClose(ws); return; }
    const rest = buf.slice(p.headerLen);
    await relayTcp(env, ws, tcp, user.id, rest);
  } catch { safeClose(ws); }
}

