function pubUser(u) {
  // safe projection for admin UI (no secrets beyond operational fields)
  return {
    id: u.id, uuid: u.uuid, name: u.name, note: u.note || "", sub: u.sub,
    enable: !!u.enable, protocols: u.protocols, quota: Number(u.quota) || 0,
    expiry: Number(u.expiry) || 0, used: { u: Number(u.used?.u) || 0, d: Number(u.used?.d) || 0 },
    lastSeen: Number(u.lastSeen) || 0, created: Number(u.created) || 0,
    quotaHit: !!u.quotaHit, expNotified: !!u.expNotified,
  };
}
async function readJson(req) {
  try { return await req.json(); } catch { return null; }
}

async function apiLogin(req, env, ctx) {
  const ip = getClientIp(req);
  const rl = await checkRateLimit(env, ip);
  if (rl.locked) return fail(`Too many attempts. Try again later.`, 429);
  const body = await readJson(req);
  const pass = body && typeof body.password === "string" ? body.password : "";
  const real = await getPanelPass(env);
  if (pass && ctEqual(pass, real)) {
    await clearLoginAttempts(env, ip);
    const s = await makeSession(env, ctx);
    const secure = new URL(req.url).protocol === "https:";
    const st = await getSettings(env);
    const maxAge = Math.floor((st.loginTtlDays || cfg(env).loginTtlDays) * 86400);
    return json({ ok: true, data: { exp: s.exp } }, 200, { "set-cookie": sessionCookie(s.token, st.loginTtlDays || cfg(env).loginTtlDays, secure) });
  }
  const rec = await recordFailedLogin(env, ip);
  sendTelegram(env, ctx, `⚠️ RIX failed login\n🕒 ${new Date().toISOString()}\n🌐 IP: ${ip}\n❌ result: wrong password\n🔢 attempts: ${rec.count}`);
  return fail("Invalid password", 401);
}

