async function apiListUsers(req, env, url) {
  const q = (url.searchParams.get("q") || "").toLowerCase().trim();
  const idx = await getIndex(env);
  const users = [];
  for (const id of idx) {
    const u = await getUser(env, id);
    if (u) users.push(u);
  }
  users.sort((a, b) => (b.created || 0) - (a.created || 0));
  let out = users;
  if (q) out = users.filter((u) => (u.name || "").toLowerCase().includes(q) || (u.uuid || "").toLowerCase().includes(q));
  return ok({ users: out.map(pubUser), total: users.length });
}

async function apiCreateUser(req, env) {
  const c = cfg(env);
  const st = await getSettings(env);
  const idx = await getIndex(env);
  if (idx.length >= (st.maxUsers || c.maxUsers)) return fail("User limit reached", 409);
  const b = (await readJson(req)) || {};
  const name = typeof b.name === "string" ? b.name.trim() : "";
  if (!validName(name)) return fail("Invalid name", 400);
  // unique name (case-insensitive)
  for (const id of idx) {
    const u = await getUser(env, id);
    if (u && u.name.toLowerCase() === name.toLowerCase()) return fail("Duplicate name", 409);
  }
  let uuid = typeof b.uuid === "string" && b.uuid.trim() ? b.uuid.trim().toLowerCase() : newUuid();
  if (!isUuid(uuid)) return fail("Invalid UUID", 400);
  if (await findByUuid(env, uuid)) return fail("Duplicate UUID", 409);
  let sub = typeof b.sub === "string" && b.sub.trim() ? b.sub.trim().toLowerCase() : newSub();
  if (!isHex(sub, 20)) return fail("Invalid sub token (20 hex)", 400);
  if (await findBySub(env, sub)) return fail("Duplicate sub", 409);
  const protocols = Array.isArray(b.protocols) && b.protocols.length ? b.protocols : st.defaultProtocols;
  if (!validProtocols(protocols)) return fail("Invalid protocols", 400);
  if (b.quota != null && !validQuota(b.quota)) return fail("Invalid quota", 400);
  if (b.expiry != null && !validExpiry(b.expiry)) return fail("Invalid expiry", 400);
  const now = Date.now();
  const u = blankUser({
    id: newId(), uuid, name, note: typeof b.note === "string" ? b.note.slice(0, 300) : "",
    sub, enable: b.enable !== false, protocols: [...new Set(protocols)],
    quota: Number(b.quota) || 0, expiry: Number(b.expiry) || 0,
    used: { u: 0, d: 0 }, created: now,
  });
  await saveUser(env, u);
  await saveIndex(env, [...idx, u.id]);
  return ok({ user: pubUser(u) }, 201);
}

async function apiBulk(req, env) {
  const c = cfg(env);
  const st = await getSettings(env);
  const b = (await readJson(req)) || {};
  const prefix = typeof b.prefix === "string" ? b.prefix.trim().slice(0, 24) : "user";
  const count = Math.floor(Number(b.count));
  if (!prefix || /[\r\n<>"]/.test(prefix)) return fail("Invalid prefix", 400);
  if (!Number.isFinite(count) || count < 1) return fail(`Count must be 1..${c.maxBulk}`, 400);
  const maxBulk = Math.min(st.maxBulk || c.maxBulk, c.maxBulk, DEFAULTS.MAX_BULK_USERS);
  if (count < 1 || count > maxBulk) return fail(`Count must be 1..${maxBulk}`, 400);
  const idx = await getIndex(env);
  const maxUsers = st.maxUsers || c.maxUsers;
  if (idx.length + count > maxUsers) return fail("Would exceed user limit", 409);
  const protocols = Array.isArray(b.protocols) && b.protocols.length ? b.protocols : st.defaultProtocols;
  if (!validProtocols(protocols)) return fail("Invalid protocols", 400);
  if (b.quota != null && !validQuota(b.quota)) return fail("Invalid quota", 400);
  if (b.expiry != null && !validExpiry(b.expiry)) return fail("Invalid expiry", 400);
  const existing = new Set();
  for (const id of idx) { const u = await getUser(env, id); if (u) existing.add(u.name.toLowerCase()); }
  const created = [];
  const nextIdx = [...idx];
  for (let i = 1; i <= count; i++) {
    const name = `${prefix}-${String(i).padStart(3, "0")}`;
    if (existing.has(name.toLowerCase())) return fail(`Duplicate name: ${name}`, 409);
    const u = blankUser({
      id: newId(), uuid: newUuid(), name, note: typeof b.note === "string" ? b.note.slice(0, 300) : "",
      sub: newSub(), enable: b.enable !== false, protocols: [...new Set(protocols)],
      quota: Number(b.quota) || 0, expiry: Number(b.expiry) || 0, used: { u: 0, d: 0 }, created: Date.now(),
    });
    await saveUser(env, u);
    nextIdx.push(u.id);
    existing.add(name.toLowerCase());
    created.push(pubUser(u));
  }
  await saveIndex(env, nextIdx);
  return ok({ users: created }, 201);
}

async function apiUpdateUser(req, env, id) {
  const u = await getUser(env, id);
  if (!u) return fail("Not found", 404);
  const b = (await readJson(req)) || {};
  if (b.name != null) {
    if (!validName(b.name)) return fail("Invalid name", 400);
    const idx = await getIndex(env);
    for (const uid of idx) {
      if (uid === id) continue;
      const o = await getUser(env, uid);
      if (o && o.name.toLowerCase() === String(b.name).trim().toLowerCase()) return fail("Duplicate name", 409);
    }
    u.name = String(b.name).trim();
  }
  if (b.note != null) u.note = String(b.note).slice(0, 300);
  if (b.uuid != null) {
    const nu = String(b.uuid).trim().toLowerCase();
    if (!isUuid(nu)) return fail("Invalid UUID", 400);
    if (nu !== u.uuid.toLowerCase()) {
      if (await findByUuid(env, nu)) return fail("Duplicate UUID", 409);
      await kvDel(env, KV_KEYS.uuid(u.uuid.toLowerCase()));
      uuidCacheDelete(u.uuid);
      u.uuid = nu;
    }
  }
  if (b.protocols != null) {
    if (!validProtocols(b.protocols)) return fail("Invalid protocols", 400);
    u.protocols = [...new Set(b.protocols)];
  }
  if (b.quota != null) {
    if (!validQuota(b.quota)) return fail("Invalid quota", 400);
    u.quota = Number(b.quota);
    if (!isQuotaHit(u)) u.quotaHit = false;
  }
  if (b.expiry != null) {
    if (!validExpiry(b.expiry)) return fail("Invalid expiry", 400);
    u.expiry = Number(b.expiry);
  }
  if (b.enable != null) u.enable = !!b.enable;
  await saveUser(env, u);
  return ok({ user: pubUser(u) });
}

async function apiDeleteUser(env, id) {
  const u = await getUser(env, id);
  if (!u) return fail("Not found", 404);
  await deleteUserAll(env, u);
  return ok({ deleted: id });
}

async function apiRenew(req, env, id) {
  const u = await getUser(env, id);
  if (!u) return fail("Not found", 404);
  const b = (await readJson(req)) || {};
  const days = Number(b.days != null ? b.days : 30);
  if (!Number.isFinite(days) || days < 1 || days > 3650) return fail("Invalid days", 400);
  const base = Number(u.expiry) > Date.now() ? Number(u.expiry) : Date.now();
  u.expiry = base + Math.floor(days) * 86400000;
  u.expNotified = false;
  await saveUser(env, u);
  return ok({ user: pubUser(u) });
}

