async function handleSub(req, env, url, token) {
  try {
    if (!isHex(token, 20)) return new Response("Not found", { status: 404 });
    const user = await findBySub(env, token);
    if (!user) return new Response("Not found", { status: 404 });
    const host = url.hostname;
    const st = await getSettings(env);
    const links = buildLinks(user, host, st.pathPrefix);
    const asTxt = url.searchParams.get("f") === "txt";
    const body = asTxt ? links.join("\n") : b64encodeStr(links.join("\n"));
    const h = {
      "content-type": "text/plain; charset=utf-8",
      "profile-title": `RIX:${user.name}`,
      "profile-update-interval": String((st.subUpdateInterval || 12)),
      "subscription-userinfo": subUserInfo(user),
      "cache-control": "no-store",
    };
    return new Response(body, { status: 200, headers: h });
  } catch {
    return new Response("error", { status: 500 });
  }
}

