.stat{background:rgba(255,255,255,0.03);border:1px solid var(--brd);padding:20px;border-radius:20px;text-align:center}.stat b{font-size:28px;display:block;margin-bottom:4px}.stat span{color:var(--mut);font-size:12px}
.panel{background:var(--glass);border:1px solid var(--brd);border-radius:24px;padding:24px;backdrop-filter:blur(20px);box-shadow:0 10px 30px rgba(0,0,0,0.3)}
.panel h3{margin:0 0 16px;font-size:16px;font-weight:800;display:flex;align-items:center;gap:8px}
table{width:100%;border-collapse:separate;border-spacing:0 8px}th{color:var(--mut);font-size:12px;text-align:right;padding:12px}td{background:rgba(255,255,255,0.02);padding:16px;border-top:1px solid var(--brd);border-bottom:1px solid var(--brd)}
td:first-child{border-left:1px solid var(--brd);border-top-left-radius:12px;border-bottom-left-radius:12px}td:last-child{border-right:1px solid var(--brd);border-top-right-radius:12px;border-bottom-right-radius:12px}
code{font-size:11px;background:rgba(0,0,0,0.45);border:1px solid var(--brd);padding:4px 8px;border-radius:8px;direction:ltr;display:inline-block;max-width:170px;overflow:hidden;text-overflow:ellipsis;font-family:monospace}
.btn{border:0;border-radius:12px;padding:8px 16px;font-weight:700;cursor:pointer;background:var(--brd);color:white;margin:2px;transition:0.3s}.btn:hover{filter:brightness(1.25)}.btn.p{background:var(--accent)}.btn.d{background:rgba(239,68,68,0.2);color:#fca5a5}.btn.g{background:rgba(52,211,153,0.14)}
