/* ============================================================
 * 13. Main router
 * ========================================================== */
export default {
  async fetch(request, env, ctx) {
    try {
      await ensureBoot(env);
      const url = new URL(request.url);
      const path = url.pathname;
      const method = request.method.toUpperCase();
      const upgrade = request.headers.get("Upgrade");

      // ---- WebSocket VPN paths (before API) ----
      if (upgrade && upgrade.toLowerCase() === "websocket") {
        return await handleWsUpgrade(request, env, ctx, url);
      }

      // ---- API ----
      if (path === "/api/login" && method === "POST") {
        try { return await apiLogin(request, env, ctx); } catch (e) { return fail("error", 500); }
      }
      if (path.startsWith("/api/")) {
        // public? none besides login. all others need auth
        let authed = false;
        try { authed = await verifySession(env, request); } catch { authed = false; }
        if (!authed) return fail("Unauthorized", 401);
        try {
          return await routeApi(request, env, ctx, url, path, method);
        } catch (e) { return fail("Internal error", 500); }
      }

      // ---- subscription ----
      if (path.startsWith("/sub/") && method === "GET") {
        const token = path.slice(5).split("/")[0].trim().toLowerCase();
        return await handleSub(request, env, url, token);
      }
      // ---- public page ----
      if (path.startsWith("/s/") && method === "GET") {
        try {
          const token = path.slice(3).split("/")[0].trim().toLowerCase();
          if (!isHex(token, 20)) return new Response("Not found", { status: 404 });
          const user = await findBySub(env, token);
          if (!user) return new Response("Not found", { status: 404 });
          const subUrl = `${url.protocol}//${url.host}/sub/${user.sub}`;
          const st = await getSettings(env);
          return new Response(publicPageHtml(user, subUrl, st), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
        } catch { return new Response("error", { status: 500 }); }
      }

      // ---- root: admin dashboard ----
      if (path === "/" || path === "/index.html") {
        if (method !== "GET") return fail("Not found", 404);
        const st = await getSettings(env);
        return new Response(adminHtml(st.title), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
      }
      return fail("Not found", 404);
    } catch (e) {
      return fail("Internal error", 500);
    }
  },
};

async function routeApi(req, env, ctx, url, path, method) {
  // logout / me
  if (path === "/api/logout" && method === "POST") {
    await destroySession(env, req);
    return json({ ok: true, data: {} }, 200, { "set-cookie": clearSessionCookie() });
  }
  if (path === "/api/me" && method === "GET") {
    const st = await getSettings(env);
    return ok({ title: st.title });
  }
  // settings
  if (path === "/api/settings" && method === "GET") {
    const st = await getSettings(env);
    return ok(st); // never includes secrets (panelPass excluded by getSettings)
  }
  if (path === "/api/settings" && method === "PUT") {
    const b = (await readJson(req)) || {};
    const patch = {};
    if (b.title != null) patch.title = String(b.title).slice(0, 80);
    if (b.announcement != null) patch.announcement = String(b.announcement).slice(0, 2000);
    if (b.maxUsers != null) { const n = Math.floor(Number(b.maxUsers)); if (!Number.isFinite(n) || n < 1 || n > 5000) return fail("Invalid maxUsers", 400); patch.maxUsers = n; }
    if (b.loginTtlDays != null) { const n = Math.floor(Number(b.loginTtlDays)); if (!Number.isFinite(n) || n < 1 || n > 90) return fail("Invalid loginTtlDays", 400); patch.loginTtlDays = n; }
    if (b.loginMaxAttempts != null) { const n = Math.floor(Number(b.loginMaxAttempts)); if (!Number.isFinite(n) || n < 1 || n > 50) return fail("Invalid loginMaxAttempts", 400); patch.loginMaxAttempts = n; }
    if (b.loginLockMinutes != null) { const n = Math.floor(Number(b.loginLockMinutes)); if (!Number.isFinite(n) || n < 1 || n > 1440) return fail("Invalid loginLockMinutes", 400); patch.loginLockMinutes = n; }
    if (b.subUpdateInterval != null) { const n = Math.floor(Number(b.subUpdateInterval)); if (!Number.isFinite(n) || n < 1 || n > 168) return fail("Invalid subUpdateInterval", 400); patch.subUpdateInterval = n; }
    if (b.pathPrefix != null) patch.pathPrefix = String(b.pathPrefix).trim().replace(/^\/+|\/+$/g, "").slice(0, 40);
    if (b.defaultProtocols != null) {
      if (!validProtocols(b.defaultProtocols)) return fail("Invalid defaultProtocols", 400);
      patch.defaultProtocols = [...new Set(b.defaultProtocols)];
    }
    const next = await saveSettings(env, patch);
    return ok(next);
  }
  // password
  if (path === "/api/password" && method === "POST") {
    const b = (await readJson(req)) || {};
    const cur = typeof b.current === "string" ? b.current : "";
    const nxt = typeof b.next === "string" ? b.next : (typeof b.new === "string" ? b.new : "");
    if (!cur || !nxt) return fail("Missing fields", 400);
    const real = await getPanelPass(env);
    if (!ctEqual(cur, real)) return fail("Current password wrong", 403);
    if (nxt.length < 6 || nxt.length > 256) return fail("New password must be 6+ chars", 400);
    await setPanelPass(env, nxt);
    await bumpSessionVersion(env);
    // wipe KV sessions
    // (version bump already invalidates; best-effort delete is skipped for scale)
    await destroySession(env, req);
    return json({ ok: true, data: {} }, 200, { "set-cookie": clearSessionCookie() });
  }
  // users collection
  if (path === "/api/users" && method === "GET") return apiListUsers(req, env, url);
  if (path === "/api/users" && method === "POST") return apiCreateUser(req, env);
