async function handleWsUpgrade(req, env, ctx, url) {
  try {
    const st = await getSettings(env);
    const prefix = normPrefix(st.pathPrefix);
    // path like /{uuid} , /{uuid}/trojan (+ optional prefix), query ?ed=2560 ignored for routing
    const rawPath = url.pathname; // e.g. /uuid or /uuid/trojan or /prefix/uuid
    const segs = rawPath.split("/").filter(Boolean);
    let uuidSeg = null, isTrojan = false;
    if (prefix) {
      // require prefix
      if (segs.length < 2 || segs[0] !== prefix) return new Response("Not found", { status: 404 });
      uuidSeg = (segs[1] || "").toLowerCase();
      isTrojan = segs[2] === "trojan";
      if (segs.length > 3 || (segs.length === 3 && !isTrojan)) return new Response("Not found", { status: 404 });
    } else {
      if (segs.length < 1 || segs.length > 2) return new Response("Not found", { status: 404 });
      uuidSeg = (segs[0] || "").toLowerCase();
      isTrojan = segs[1] === "trojan";
      if (segs.length === 2 && !isTrojan) return new Response("Not found", { status: 404 });
    }
    if (!isUuid(uuidSeg)) return new Response("Not found", { status: 404 });
    const user = await findByUuid(env, uuidSeg);
    if (!user) return new Response("Not found", { status: 404 });
    if (!user.enable) return new Response("Forbidden", { status: 403 });
    const wantProto = isTrojan ? "trojan" : "vless";
    if (!Array.isArray(user.protocols) || !user.protocols.includes(wantProto)) return new Response("Forbidden", { status: 403 });
    if (isExpired(user)) return new Response("Expired", { status: 403 });
    if (isQuotaHit(user)) return new Response("Quota", { status: 403 });

    // CRITICAL: create WS pair and return 101 immediately. Never wait for packets first.
    const pair = new WebSocketPair();
    const client = pair[0], server = pair[1];
    try { server.accept(); } catch { return new Response("error", { status: 500 }); }
    const early = decodeEarlyData(req.headers.get("sec-websocket-protocol") || "");
    const userSnap = { id: user.id, uuid: user.uuid };
    const mode = wantProto;
    ctx.waitUntil((async () => {
      try {
        // re-fetch fresh user inside async task (quota/expiry may have changed)
        const fresh = await getUser(env, userSnap.id);
        const u = fresh || user;
        if (mode === "trojan") await handleTrojanSession(env, server, u, early);
        else await handleVlessSession(env, server, u, early);
      } catch {
        safeClose(server);
      }
    })());
    return new Response(null, { status: 101, webSocket: client });
  } catch {
    return new Response("error", { status: 500 });
  }
}


