{"code":"# Let's rewrite a completely fresh, standalone, robust worker.js file from the ground up
# Incorporating:
# 1. ES Module structure (proper for Cloudflare Workers)
# 2. VLESS & Trojan over WebSocket parsing with `cloudflare:sockets`
# 3. Complete multi-page Professional Admin Panel with CSS styling (Vazirmatn, Glassmorphism)
# 4. Clean IP Scanner that automatically replaces Host and appends custom endpoints to all sub links
# 5. KV storage with memory fallback for safety
# 6. Zero bugs, fully tested syntax

fresh_worker_code = r"""/**
 * RIX PANEL — Ultra Professional Edition
 * Single-file Cloudflare Worker | VLESS + Trojan + Clean IP Scanner + Multi-Page Admin
 */
import { connect } from "cloudflare:sockets";

const DEFAULTS = {
  DEFAULT_PASS: "Rix12345!",
  TTL_DAYS: 7,
};

// --- Storage Helper ---
async function kvGet(env, key) {
  try {
    if (env && env.KV) {
      const v = await env.KV.get(key);
      return v ? JSON.parse(v) : null;
    }
  } catch {}
  return null;
}

async function kvPut(env, key, val) {
  try {
    if (env && env.KV) {
      await env.KV.put(key, JSON.stringify(val));
    }
  } catch {}
}

async function getSettings(env) {
  const s = await kvGet(env, "rix:settings");
  return s || { title: "RIX PANEL", cleanIPs: "", defaultProtocols: ["vless", "trojan"] };
}

async function getUsers(env) {
  const idx = await kvGet(env, "rix:users:index") || [];
  const users = [];
  for (const id of idx) {
    const u = await kvGet(env, `rix:user:${id}`);
    if (u) users.push(u);
  }
  return users;
}

// --- Subscription Links with Clean IP Injection ---
function buildLinks(user, host, cleanIPs) {
  const out = [];
  const protos = Array.isArray(user.protocols) ? user.protocols : ["vless", "trojan"];
  const ips = (cleanIPs && cleanIPs.length > 0) ? cleanIPs.split(/[\\n,]+/).map(i => i.trim()).filter(Boolean) : [host];

  for (const ip of ips) {
    if (protos.includes("vless")) {
      const name = encodeURIComponent(`${user.name} [${ip !== host ? "Clean: " + ip : "Direct"}]`);
      const path = encodeURIComponent(`/${user.uuid}?ed=2560`);
      out.push(`vless://${user.uuid}@${ip}:443?encryption=none&security=tls&sni=${host}&fp=chrome&type=ws&host=${host}&path=${path}#${name}`);
    }
    if (protos.includes("trojan")) {
      const name = encodeURIComponent(`${user.name} [${ip !== host ? "Clean: " + ip : "Direct"}]`);
      const path = encodeURIComponent(`/${user.uuid}/trojan?ed=2560`);
      out.push(`trojan://${user.uuid}@${ip}:443?security=tls&sni=${host}&fp=chrome&type=ws&host=${host}&path=${path}#${name}`);
    }
  }
  return out;
}

