    <p>وضعیت سیستم: آماده به کار | کل کاربران: ${users.length}</p>
  </div>

  <div class="card">
    <h3>🔍 اسکنر و تزریق IP تمیز (Clean IP)</h3>
    <p style="color: #94a3b8; font-size: 13px;">IPهای تمیز را در زیر وارد کنید (هر خط یک IP). این IPها به طور خودکار جایگزین هاست اصلی در لینک‌های سابسکریپشن تمامی کاربران می‌شوند.</p>
    <form method="POST" action="/admin/scanner">
      <textarea name="cleanIPs" placeholder="104.16.x.x\\n162.159.x.x">${settings.cleanIPs || ''}</textarea>
      <button type="submit">ذخیره و اعمال فوری به تمام کانفیگ‌ها</button>
    </form>
  </div>
  </body></html>`;
}

// --- Main Worker Fetch Handler ---
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // Admin Panel Route
    if (path === "/admin") {
      const settings = await getSettings(env);
      const users = await getUsers(env);
      return new Response(renderAdmin(settings, users), { headers: { "content-type": "text/html; charset=utf-8" } });
    }

    // Save Scanner IPs Route
    if (path === "/admin/scanner" && request.method === "POST") {
      const formData = await request.formData();
      const cleanIPs = formData.get("cleanIPs") || "";
      const settings = await getSettings(env);
      settings.cleanIPs = cleanIPs;
      await kvPut(env, "rix:settings", settings);
      return Response.redirect(new URL("/admin", request.url).toString(), 303);
    }

    // Subscription Route (/sub/{token})
    if (path.startsWith("/sub/")) {
      const token = path.slice(5).trim();
      // Find user by sub token
      const idx = await kvGet(env, "rix:users:index") || [];
      let targetUser = null;
      for (const id of idx) {
        const u = await kvGet(env, `rix:user:${id}`);
        if (u && u.sub === token) { targetUser = u; break; }
      }
      if (!targetUser) return new Response("Not found", { status: 404 });

      const settings = await getSettings(env);
      const links = buildLinks(targetUser, url.hostname, settings.cleanIPs);
      const encoded = btoa(links.join("\\n"));

      return new Response(encoded, {
        headers: {
          "content-type": "text/plain; charset=utf-8",
          "profile-title": `RIX: ${targetUser.name}`,
          "cache-control": "no-store"
        }
      });
    }

    return new Response("RIX Panel Core Active. Go to /admin", { status: 200 });
  }
};
"""

with open("/data/workspace/rix-panel/worker.js", "w") as f:
